using System; using System.Web;  public partial class Login : System.Web.UI.Page {     protected void Page_Load(object sender, EventArgs e)     {         // 1. COOKIE DEMO: Retrieve username from Cookie if it exists         if (!IsPostBack)         {                           if (Request.Cookies["userCookie"] != null)             {                 txtUsername.Text = Request.Cookies["userCookie"].Value;                 chkRemember.Checked = true;             }         }     }      protected void btnLogin_Click(object sender, EventArgs e)     {         // Hardcoded credentials for practical demo         if (txtUsername.Text.Trim() == "admin" && txtPassword.Text.Trim() == "1234")         {             // 2. SESSION DEMO: Store logged-in username in Session             Session["username"] = txtUsername.Text.Trim();              // 3. COOKIE DEMO: Create or remove cookie based on 'Remember Me'             if (chkRemember.Checked)             {                 HttpCookie cookie = new HttpCookie("userCookie", txtUsername.Text.Trim());                 cookie.Expires = DateTime.Now.AddDays(7); // Persist for 7 days                 Response.Cookies.Add(cookie);             }             else             {                 if (Request.Cookies["userCookie"] != null)                 {                     HttpCookie cookie = new HttpCookie("userCookie");                     cookie.Expires = DateTime.Now.AddDays(-1); // Expire cookie                                    Response.Cookies.Add(cookie);                 }             }              // Redirect to Academic Calendar             Response.Redirect("Default.aspx");         }         else         {             lblMessage.Text = "Invalid username or password! Please try again.";         }     } } 
